const L=(id,module,title,en,source,idea,sections,example,trap)=>({id,module,title,en,source,idea,sections,example,trap});
export const lessons=[
L('atoms','start','Атом, ион и химическая запись','Atoms, ions & formulas','Вводный материал для лекций 9–16',
'Молекула похожа на конструкцию из деталей: атомы — детали, связи — соединения. Но это модель: настоящие атомы не твёрдые шарики.',[
['Что означают символы','Атом содержит положительное ядро и отрицательные электроны. В нейтральном атоме число протонов равно числу электронов. Потерял электрон — стал положительным ионом, получил — отрицательным. Заряд +2 означает недостаток двух электронов, а не два лишних протона.'],
['Индекс и коэффициент','H₂O: два атома H и один O в одной молекуле. 3H₂O: три молекулы воды, всего 6 H и 3 O. Индекс меняет вещество; коэффициент меняет количество. Балансировать реакцию можно коэффициентами, но не индексами.'],
['Как читать уравнение','2H₂(g) + O₂(g) → 2H₂O(l). На две порции водорода нужна одна порция кислорода. (g) — газ, (l) — жидкость, (s) — твёрдое, (aq) — растворено в воде. Стрелка ⇌ означает обратимый процесс.'],
['Электроны на внешнем уровне','Валентные электроны участвуют в химических связях. Для главных подгрупп: H — 1, C — 4, N — 5, O — 6, F и Cl — 7. Связывающая пара принадлежит связи; неподелённая пара (lone pair) остаётся у одного атома.']
],['Сколько электронов у NH₄⁺?','N даёт 5, четыре H дают 4. Положительный заряд означает убрать 1: 5 + 4 − 1 = 8 валентных электронов. Это четыре пары для четырёх N–H связей.'],'У положительного иона электроны вычитают. У отрицательного — добавляют.'),
L('moles','start','Моль — удобная большая пачка','Mole & molar mass','Вводный материал для расчётных задач',
'Дюжина — это 12 штук. Моль — это 6.022 × 10²³ частиц. Так химик переводит невидимые молекулы в граммы на весах.',[
['Главные величины','n — количество вещества в mol. m — масса в g. M — молярная масса в g/mol: масса одного моля. Для воды M ≈ 2×1 + 16 = 18 g/mol. Молярная масса не равна массе образца.'],
['Три перевода','n = m/M; m = nM; N = nNₐ. Здесь N — число частиц, Nₐ = 6.022 × 10²³ mol⁻¹. Проверяй единицы: g ÷ (g/mol) = mol.'],
['Концентрация','c = n/V, где V в литрах, c в mol/L, также обозначается M. 0.20 M означает 0.20 mol в литре раствора. В задаче с 250 mL сначала переведи объём: 0.250 L. При разбавлении без реакции c₁V₁ = c₂V₂.'],
['Лимитирующий реагент','Сначала уравняй реакцию. Раздели количество каждого реагента на его коэффициент. Наименьшее отношение определяет, сколько раз может пройти реакция. Именно этот реагент закончится первым.']
],['Смешали 4 mol H₂ и 3 mol O₂. Сколько получится H₂O?','В 2H₂ + O₂ → 2H₂O сравни 4/2 = 2 и 3/1 = 3. Водород лимитирует. Получится 2×2 = 4 mol воды; останется 3−2 = 1 mol O₂.'],'Не подставляй граммы прямо в соотношение коэффициентов: сначала переведи в моли.'),
L('units','start','Единицы, степени и логарифмы','Units & logarithms','Вводный материал; лекция 11, с. 23',
'Число без единицы — как адрес без города. Один и тот же объём можно записать в литрах или м³, но формула должна понимать твою запись.',[
['Переводы, которые нужны постоянно','T(K) = t(°C) + 273.15. 1 L = 10⁻³ m³; 1 mL = 10⁻³ L; 1 kg = 1000 g; 1 kJ = 1000 J. 1 atm = 760 Torr = 101325 Pa. Разность температур ΔT одинакова в K и °C.'],
['Выбор R','R = 0.082057 L·atm/(mol·K) для литров и атмосфер. R = 8.314 J/(mol·K) для Pa и m³, а также для энергий в J. R = 0.008314 kJ/(mol·K) для энергий в kJ. Температура в газовых формулах всегда абсолютная.'],
['Как читать 10 в степени','2.5 × 10⁻³ = 0.0025; 3 × 10⁴ = 30000. При делении степеней показатели вычитают: 10⁻¹⁴/10⁻⁵ = 10⁻⁹. В калькуляторе запись 2.5e-3 означает то же самое.'],
['log и ln','log — десятичный логарифм: log(10⁻³) = −3. Поэтому −log(10⁻³) = 3. ln — натуральный логарифм, нужен в формулах работы и энергии Гиббса. ln(2) ≈ 0.693; log(2) ≈ 0.301. Это разные кнопки.'],
['Разумное округление','Оставляй несколько запасных цифр в промежуточных шагах и округляй только итог. Если варианты близкие, проверь Kelvin, массу в kg/g и знак. В заданиях сайта единицы и нужная точность указаны.']
],['25 °C, 500 mL, 2 atm: как записать для SI?','T = 298.15 K; V = 0.000500 m³; P = 202650 Pa. После этого можно использовать R = 8.314.'],'В ΔG = ΔH − TΔS нельзя вычитать kJ и J. Сначала приведи их к одной единице.'),
L('lewis','bond','Структура Льюиса и формальный заряд','Lewis structures & formal charge','Лекция 9, с. 1–14',
'Рисунок Льюиса — бухгалтерия электронов. Каждая черта между атомами — два электрона. Каждые две точки возле атома — ещё одна пара.',[
['Алгоритм рисунка','1. Сосчитай валентные электроны с учётом заряда. 2. Выбери центральный атом (H никогда не центральный). 3. Соедини одинарными связями. 4. Дополни внешние атомы до октета, H до двух электронов. 5. Поставь остаток на центральный атом. 6. При необходимости преврати lone pairs внешних атомов в кратные связи.'],
['Формальный заряд','FC = V − N − B/2. V — валентные электроны свободного атома; N — несвязывающие электроны; B — электроны во всех связях атома. Удобно: FC = V − число точек − число черточек. Сумма FC равна заряду всей частицы.'],
['Выбор разумной структуры','Обычно предпочитай заполненные октеты атомов второго периода, небольшие формальные заряды и отрицательный заряд на более электроотрицательном атоме. Правила сравнивают вклад структур, а не запрещают все заряженные структуры. У CO важная структура содержит C⁻ и O⁺.'],
['Границы правила октета','H нужен дублет. У Be и B возможен неполный октет. У C, N, O, F нельзя размещать больше восьми электронов в обычной структуре Льюиса. Для элементов третьего и последующих периодов в учебных Lewis-структурах возможен расширенный октет.']
],['Формальные заряды в :C≡O:','У каждого атома одна lone pair и тройная связь. C: 4−2−3 = −1. O: 6−2−3 = +1. Общий заряд 0. У обоих атомов октет.'],'Формальный заряд — модель распределения электронов, не экспериментально измеренный частичный заряд.'),
L('resonance','bond','Резонанс: один объект, несколько рисунков','Resonance & delocalization','Лекция 9, с. 1–14',
'Несколько рисунков могут описывать одну молекулу, как несколько карт одного города. Молекула не прыгает между рисунками: электроны распределены по общей структуре.',[
['Что можно менять','Меняются положения электронов, а атомный каркас остаётся тем же. Изогнутая стрелка начинается на lone pair или π-связи и показывает движение пары электронов. Типичные ходы: lone pair → π-связь; π-связь → lone pair; π-связь → соседняя π-связь.'],
['Что сохраняется','Общее число электронов, общий заряд и расположение атомов. Не двигай H, не разрывай σ-каркас ради резонансной формы. Не перегружай октет C, N, O, F: при добавлении π-связи иногда нужно одновременно убрать соседнюю π-пару.'],
['Почему связи становятся одинаковыми','У CO₃²⁻ три эквивалентных рисунка: двойная связь с каждым O по очереди. В реальности три C–O связи одинаковые, с порядком 4/3. Их длина между длинами соответствующей одинарной и двойной связи.'],
['Какие формы важнее','Эквивалентные формы вносят одинаковый вклад. Сильно разделённые заряды обычно менее выгодны. Но полярная C=O имеет важный вклад C⁺–O⁻. В сопряжённой системе p-орбитали соседствуют; π-электроны могут делокализоваться. В бензоле все C sp², а шесть π-электронов делокализованы по кольцу.'],
['Примеры из лекции','В N₂O с каркасом N–N–O важна форма N≡N⁺–O⁻ и есть вклад ⁻N=N⁺=O. У сложного эфира lone pair соседнего O сопряжена с карбонилом. При кислотном катализе обычно предпочитается протонирование карбонильного O; слово «никогда» для второго O было бы слишком сильным.']
],['Почему в CO₃²⁻ нет одной постоянной двойной связи?','Рисунки эквивалентны, а измеренные связи одинаковы. Суммарный порядок 2+1+1 = 4 распределяется по трём связям: 4/3.'],'Стрелка ↔ между резонансными формами не равна стрелке ⇌ химического равновесия.'),
L('vsepr','bond','Форма молекулы по VSEPR','Electron domains & molecular geometry','Лекция 9, с. 32–46',
'Представь несколько воздушных шариков вокруг одного узла. Они отталкиваются и занимают места подальше друг от друга. Электронные области ведут себя похоже.',[
['Сначала посчитай области','Любая связь — один electron domain: одинарная, двойная и тройная. Каждая неподелённая пара — ещё один domain. В AXₘEₙ: A — центр, X — связанный атом, E — lone pair. Число областей = m+n.'],
['Расположение всех областей','2: linear, 180°. 3: trigonal planar, 120°. 4: tetrahedral, 109.5°. 5: trigonal bipyramidal, 90° и 120°. 6: octahedral, 90°. Это электронная геометрия, включающая lone pairs.'],
['Форма только по атомам','AX₂ — linear (CO₂); AX₃ — trigonal planar (BF₃); AX₂E — bent (SO₂); AX₄ — tetrahedral (CH₄); AX₃E — trigonal pyramidal (NH₃); AX₂E₂ — bent (H₂O). У воды электронная геометрия тетраэдрическая, молекулярная — угловая.'],
['Пять и шесть областей','AX₅ PF₅ — trigonal bipyramidal. AX₄E SF₄ — seesaw; AX₃E₂ ClF₃ — T-shaped; AX₂E₃ XeF₂ — linear. Lone pairs занимают экваториальные позиции в тригональной бипирамиде. AX₆ SF₆ — octahedral; AX₅E XeF₅⁺ — square pyramidal; AX₄E₂ XeF₄ — square planar, пары напротив.'],
['Почему углы отличаются','Lone pair отталкивает сильнее связывающей пары: в NH₃ угол около 107°, в H₂O около 104.5°. Кратная связь занимает одну область, но может сильнее отталкивать соседние связи. В молекуле с несколькими центрами анализируй каждый центр отдельно.']
],['Какая форма у NH₃?','У N три N–H связи и одна lone pair: четыре области, AX₃E. Электронная геометрия tetrahedral; форма по атомам trigonal pyramidal.'],'Тройная связь считается одной областью, хотя содержит три электронные пары.'),
L('hybrid','bond','Гибридизация и σ/π-связи','Hybridization & valence bond theory','Лекция 9, с. 15–31, 47–48; Mid №10,16',
'Гибридизация — способ описать направленные орбитали одного атома. Мы математически смешиваем его s- и p-орбитали, чтобы объяснить наблюдаемую геометрию.',[
['Два типа перекрывания','σ-связь возникает при перекрывании вдоль оси между ядрами. π-связь — при боковом перекрывании p-орбиталей. Одинарная = 1σ; двойная = 1σ+1π; тройная = 1σ+2π. Между двумя атомами только одна σ-связь.'],
['Быстрая таблица','2 области → sp: две гибридные орбитали, 180°, остаются две p. 3 области → sp²: три гибридные, 120°, остаётся одна p. 4 области → sp³: четыре гибридные, тетраэдрическое расположение. Гибридизуются орбитали, а не электроны.'],
['Углерод на примерах','В CH₄ углерод sp³, четыре σ. В C₂H₄ каждый C sp², свободная p образует π. В C₂H₂ каждый C sp, две p образуют две взаимно перпендикулярные π-связи. В N₂ каждый N можно описать как sp: одна гибридная орбиталь для σ, другая для lone pair.'],
['Нюанс расширенного октета','В лекции используются обозначения dsp³ и d²sp³ для пяти и шести областей. Узнавай эту учебную таблицу, но современное описание гипервалентной связи не требует существенной d-гибридизации. VSEPR надёжнее использовать как модель геометрии.'],
['Гибридизация и основность','В сопоставимых случаях больше s-характера → пара ближе к ядру и ниже по энергии → её сложнее отдать протону. sp имеет 50% s, sp² — 33%, sp³ — 25%. Поэтому пара амина обычно доступнее, чем пара нитрила; резонанс и среда тоже важны.']
],['Сколько σ и π в этилене C₂H₄?','Четыре C–H дают 4σ. C=C даёт 1σ+1π. Всего 5σ и 1π. Каждый C имеет три направления связей, значит sp².'],'Гибридные орбитали принадлежат одному атому. Молекулярные орбитали относятся ко всей молекуле.'),
L('mo-fill','mo','Молекулярные орбитали без мистики','MO diagrams & electron filling','Лекция 10, с. 1–23, 30–34',
'Орбитали похожи на этажи для электронов. Сначала занимаются нижние этажи. Но орбиталь — область, описанная волновой функцией, а не траектория полёта электрона.',[
['От атомных к молекулярным','Из двух взаимодействующих AO получаются две MO: связывающая ниже по энергии и разрыхляющая выше. В первой волны складываются и увеличивают плотность между ядрами, во второй между ядрами появляется узел. Число орбиталей сохраняется. Звёздочка * обозначает antibonding.'],
['Три правила заселения','Aufbau: снизу вверх. Pauli: максимум два электрона в одной орбитали, с противоположными спинами. Hund: равные по энергии орбитали сначала получают по одному электрону с параллельными спинами. πₓ и πᵧ — две разные орбитали одинаковой энергии.'],
['Порядок уровней второго периода','Для B₂, C₂, N₂: σ2s < σ*2s < π2p < σ2p < π*2p < σ*2p. Для O₂, F₂: σ2s < σ*2s < σ2p < π2p < π*2p < σ*2p. Причина различия — s–p mixing. В диаграммах используем валентные электроны; заполненные 1s уровни взаимно сокращаются в порядке связи.'],
['Симметрия тоже важна','Чтобы AO взаимодействовали, нужны подходящая симметрия и близкая энергия. σ — осевое перекрывание, π — боковое. g/u характеризуют сохранение/смену знака при инверсии для молекул с центром инверсии; это не обозначения заряда.']
],['Как заполнить валентные MO у N₂?','Всего 5+5=10 электронов. σ2s², σ*2s², π2p⁴, σ2p². Все спарены. Удаляя электрон для N₂⁺, убираем его из верхней занятой σ2p.'],'Не переноси порядок σ2p и π2p от O₂ на N₂: в лекции показаны две схемы.'),
L('mo-bond','mo','Порядок связи и магнетизм','Bond order & magnetism','Лекция 10, с. 11–16, 24–29, 32–40; Quiz №14,18',
'Связывающие электроны укрепляют связь, разрыхляющие ослабляют. Порядок связи показывает итоговый баланс.',[
['Главная формула','BO = (N bonding − N antibonding)/2. Считай электроны, а не просто занятые квадратики. Для H₂: (2−0)/2=1. Для H₂⁺: (1−0)/2=0.5. В простой модели He₂ и Be₂ имеют BO=0: обычная ковалентная связь моделью не предсказывается.'],
['Магнетизм','Есть хотя бы один неспаренный электрон → paramagnetic. Все электроны спарены → diamagnetic. У O₂ два электрона отдельно занимают две π* орбитали: он парамагнитен. У O₂⁺ один неспаренный электрон, поэтому он тоже парамагнитен.'],
['Кислородный ряд','O₂⁺: BO 2.5; O₂: 2; O₂⁻: 1.5; O₂²⁻: 1. Чем больше порядок связи в этом ряду, тем короче и обычно прочнее связь. Поэтому длина растёт O₂⁺ < O₂ < O₂⁻ < O₂²⁻.'],
['Азот и фтор','N₂: BO 3, диамагнитен; N₂⁺: BO 2.5, парамагнитен, связь длиннее. F₂: BO 1; удаление электрона из π* даёт F₂⁺ с BO 1.5. Это означает более сильную связь в модели, но не универсальную химическую «стабильность» иона.'],
['Изоэлектронные частицы','CO, N₂ и CN⁻ имеют одинаковое число электронов (14 всего, 10 валентных) и в простом описании тройную связь. N₂ и O₂ не изоэлектронны. Для заряда + убери электрон с HOMO, для − добавь на следующий доступный уровень.']
],['Что изменится при O₂ → O₂⁻?','Добавляется электрон на разрыхляющую π*. BO падает с 2 до 1.5. Связь удлиняется. Остаётся один неспаренный электрон — частица парамагнитна.'],'Неспаренность определяют по заполнению орбиталей; одного значения BO недостаточно.'),
L('frontier','mo','HOMO, LUMO и химическая реакция','Frontier orbitals & polyatomic MOs','Лекция 10, с. 35–40; лекция 11, с. 1–12',
'Реакция часто начинается там, где одна частица может отдать электронную пару, а другая имеет подходящее свободное место.',[
['Две главные аббревиатуры','HOMO — Highest Occupied Molecular Orbital, самая высокая занятая MO. LUMO — Lowest Unoccupied Molecular Orbital, самая низкая незанятая MO. Электронный донор взаимодействует своей HOMO с LUMO акцептора.'],
['Не все орбитали образуют связь','В HF при оси z вдоль связи 1s водорода взаимодействует главным образом с 2p_z фтора. 2p_x и 2p_y имеют неподходящую симметрию и остаются несвязывающими. Низкая по энергии 2s F также преимущественно несвязывающая.'],
['Разные атомы — разные энергии','У более электроотрицательного атома валентные AO обычно ниже по энергии. Поэтому гетероядерная MO-диаграмма несимметрична. В CO реакционно важная неподелённая пара HOMO имеет большой вклад углерода.'],
['Многоатомные молекулы','Для линейного BeH₂ сначала строят симметричную и антисимметричную комбинации двух H 1s; они взаимодействуют с Be 2s и 2p_z. В рассматриваемом наборе из четырёх AO получаются четыре MO. Для CH₄ четыре комбинации H взаимодействуют с C 2s и тремя 2p; восемь валентных электронов занимают четыре связывающие MO.'],
['Связь с органической реакцией','В CH₃O⁻ + CH₃Br → CH₃OCH₃ + Br⁻ lone pair кислорода служит донором. Она взаимодействует с σ* орбиталью C–Br, что одновременно помогает формированию C–O и разрыву C–Br.']
],['Какая орбиталь принимает электронную пару?','LUMO акцептора. HOMO уже содержит электроны и выступает источником. Это объясняет связь между Lewis base (донор пары) и реакционной HOMO.'],'HOMO означает highest occupied, а не highest unoccupied.'),
L('ideal','gas','PV = nRT: четыре величины в одной истории','Ideal gas & combined gas law','Лекция 11, с. 14–26; Mid №6; Quiz №5,20',
'Давление возникает от ударов молекул о стенки. Больше молекул или выше температура — больше давление. Больше места — меньше давление.',[
['Что в формуле','PV=nRT. P — абсолютное давление, V — объём, n — моли, T — Kelvin. Вырази неизвестное до подстановки. Массу сначала переводи в n=m/M. Для CO M=28.01 g/mol.'],
['Частные законы','Boyle: P₁V₁=P₂V₂ при постоянных n,T. Charles: V₁/T₁=V₂/T₂ при постоянных n,P. При постоянных n,V: P₁/T₁=P₂/T₂. Avogadro: V/n постоянно при T,P.'],
['Изменилось несколько условий','Для постоянного n: P₁V₁/T₁=P₂V₂/T₂. Если добавили газ: P₁V₁/(n₁T₁)=P₂V₂/(n₂T₂). В жёстком сосуде V сокращается, поэтому n₂=n₁(P₂/P₁)(T₁/T₂). Добавленное количество = n₂−n₁.'],
['Как выглядят графики','При постоянных T,n график P от V — убывающая гипербола. P от 1/V — возрастающая прямая через начало. PV от V — горизонтальная линия. Прямая с отрицательным наклоном P от 1/V неверна.'],
['Стандартные условия','В задачах используй конкретные P и T. Не подставляй автоматически 22.4 L/mol. В слайдах встречаются разные соглашения о standard conditions; это не заменяет заданных условий. Давление барометра P=ρgh.']
],['В жёстком сосуде 1.20 mol, 320 Torr, 25 °C. После добавления газа: 650 Torr, 40 °C. Сколько добавили?','n₂=1.20×650/320×298.15/313.15=2.321 mol. n_added=2.321−1.20=1.121 mol ≈1.12 mol.'],'2.32 mol — итоговое количество, а вопрос может спрашивать только добавленное.'),
L('mixtures','gas','Смеси, плотность и газ над водой','Dalton law & wet gas collection','Лекция 11, с. 27–38; Mid №12; Quiz №15',
'В смеси каждый газ добавляет свою долю давления. Если газ собран над водой, водяной пар тоже занимает место в этой сумме.',[
['Парциальное давление','P_total=ΣPᵢ. Мольная доля χᵢ=nᵢ/n_total; Pᵢ=χᵢP_total. Сумма мольных долей равна 1. Отношение 1:1:2 означает четыре доли всего, а не три. Массовая доля не равна мольной.'],
['Плотность','ρ=m/V=PM/(RT); M=ρRT/P. С R в L·atm и M в g/mol получаем g/L. Чем выше P при той же T, тем плотнее газ. Чем выше T при том же P, тем ниже плотность.'],
['Сбор над водой','P_dry=P_total−P_water. Затем n_dry=P_dry V/(RT). Для связи с массой металла используй коэффициенты реакции. В Zn + 2HCl → ZnCl₂ + H₂ на 1 mol H₂ нужен 1 mol Zn.'],
['Разность уровней','Если уровни жидкости в сосуде и снаружи различаются, сначала учитывают гидростатическую разность давления ±ρgh. В примере с ртутью, поднявшейся внутри на 200 mm при P_atm=750 Torr, P_gas=550 Torr. Выбирать знак нужно по схеме уровней.'],
['Молекулярная формула','Найди M по плотности. Из массовых процентов возьми условные 100 g, раздели каждую массу на атомную массу и найди целочисленное отношение. Сравни молярную массу простейшей формулы с найденной M.']
],['Собрали 240 mL H₂ при 30 °C, P_total=1.032 atm, P_water=0.042 atm. Масса Zn?','P_H₂=0.990 atm. n=0.990×0.240/(0.082057×303.15)=0.00955 mol. m_Zn=n×65.38≈0.625 g.'],'Вычитай давление пара до PV=nRT. Иначе посчитаешь воду как водород.'),
L('gas-reaction','gas','Газовые реакции: сначала химия, потом PV=nRT','Gas stoichiometry','Лекция 11, с. 39–41',
'Газовая формула говорит, сколько вещества в сосуде. Химическое уравнение говорит, сколько вещества останется после реакции. Эти шаги нельзя менять местами.',[
['Надёжный порядок','1. Уравняй реакцию. 2. Найди начальные моли каждого газа. 3. Определи лимитирующий реагент. 4. Вычти израсходованные и прибавь продукты. 5. Посчитай давление или объём конечной смеси.'],
['Когда можно сравнивать объёмы','Для газов при одинаковых T и P объёмы пропорциональны молям. В 2ZnS + 3O₂ → 2ZnO + 2SO₂ из 1 L O₂ с избытком ZnS получится 2/3 L SO₂ при тех же условиях. Твёрдые вещества не входят в отношение газовых объёмов.'],
['Общий сосуд','После соединения сосудов доступный объём обычно равен сумме их объёмов. Если температура не меняется, удобно считать PᵢVᵢ как величину, пропорциональную nᵢ. После реакции дели оставшиеся значения на общий V.']
],['6 L NO при 0.5 atm и 1.5 L O₂ при 2.5 atm смешали при неизменной T. 2NO+O₂→2NO₂.','Начальные nRT: NO=3 L·atm, O₂=3.75. NO лимитирует: O₂ потратит 1.5, останется 2.25; NO₂ получится 3. В V=7.5 L: P_NO₂=0.4 atm, P_O₂=0.3 atm; всего 0.7 atm.'],'Не складывай исходные давления напрямую: после смешивания изменился доступный объём и произошла реакция.'),
L('kmt','gas','Скорости, столкновения и свободный пробег','Kinetic molecular theory','Лекция 12, с. 1–20; Quiz №1',
'Молекулы газа постоянно движутся и сталкиваются. Температура показывает среднюю поступательную энергию, но не означает, что все частицы имеют одну скорость.',[
['Идеальная модель','Частицы имеют пренебрежимо малый собственный объём, не притягиваются и сталкиваются упруго. Давление создают удары о стенки. Для одной частицы средняя поступательная энергия 3k_BT/2, для моля 3RT/2.'],
['Три скорости','v_mp=√(2RT/M); v_mean=√(8RT/(πM)); v_rms=√(3RT/M). M обязательно в kg/mol при R=8.314. Для распределения Максвелла v_mp < v_mean < v_rms.'],
['Как меняется распределение','Повышение T расширяет кривую и смещает максимум вправо. Более тяжёлый газ при той же T движется медленнее. Средняя поступательная энергия при одной T одинакова для лёгкого и тяжёлого газа. Скорость растёт как √T, а не как T.'],
['Столкновения','σ=πd² — collision cross section для одинаковых сфер диаметра d. Z — столкновения одной молекулы за секунду. λ — mean free path, среднее расстояние между столкновениями. Z=√2 Nₐσv_mean P/(RT); λ=v_mean/Z=RT/(√2 NₐσP).'],
['Что следует без вычислений','При постоянной T удвоение P удвоит Z и уменьшит λ вдвое. При постоянном P рост T увеличивает λ; Z пропорциональна 1/√T в этой модели. Запах распространяется медленнее молекулярной скорости из-за множества столкновений.']
],['Как изменится v_rms, если T вырастет с 300 до 1200 K?','Отношение = √(1200/300)=√4=2. Скорость удвоится. Средняя поступательная энергия при этом увеличится в 4 раза.'],'Средняя скорость — не то же самое, что среднеквадратичная. Вектор скорости содержит направление; speed — только величину.'),
L('real-gas','gas','Реальные газы и эффузия','Van der Waals & Graham law','Лекция 12, с. 21–38; лекция 13, с. 1–4; Quiz №11,13',
'Настоящие молекулы занимают место и притягиваются. А через маленькое отверстие лёгкий газ в одинаковых условиях обычно выходит быстрее.',[
['Когда идеальная модель хороша','Низкое давление, высокая температура, слабые межмолекулярные взаимодействия. При высоком давлении собственный объём частиц важен, при низкой температуре притяжение становится заметнее.'],
['Уравнение ван-дер-Ваальса','(P+a(n/V)²)(V−nb)=nRT. Для расчёта давления: P=nRT/(V−nb)−a(n/V)². b учитывает исключённый объём, a — притяжение, уменьшающее измеренное давление. Нужно V>nb. Единицы a,b,R,V должны согласовываться.'],
['Эффузия и диффузия','Effusion — выход через очень маленькое отверстие в вакуум. Diffusion — перемешивание через движение и столкновения. Закон Грэма для сравнения эффузии при одинаковых условиях: r_A/r_B=√(M_B/M_A). Для равных количеств t_A/t_B=√(M_A/M_B).'],
['Как не перевернуть дробь','Лёгкий газ быстрее: его r больше, его t меньше. Если неизвестный газ выходит за половину времени, его масса в четыре раза меньше. Сначала предскажи направление, потом подставляй числа.']
],['O₂ выходит за 100 s, неизвестный газ за 50 s. Найди M.','M_unknown/M_O₂=(t_unknown/t_O₂)². M_unknown=32×(50/100)²=8 g/mol.'],'Времена и скорости стоят в противоположных отношениях. Время не пропорционально 1/√M.'),
L('energy','thermo','Теплота и работа: правило знаков','First law, heat & work','Лекция 13, с. 5–26; Mid №24',
'Считай энергию как деньги на счёте системы: получила — плюс, отдала — минус. Теплота и работа — два способа перевода энергии.',[
['Система и окружающая среда','Открытая система обменивается веществом и энергией. Закрытая — энергией, но не веществом. Изолированная не обменивается ни тем, ни другим. Нулевой закон: если две системы в тепловом равновесии с третьей, они в равновесии друг с другом.'],
['Первый закон','ΔU=q+w. В лекциях U также обозначается E. q>0 — тепло входит, q<0 — выходит. w>0 — работа совершается над системой, w<0 — система работает на окружающую среду. Теплота — энергия в передаче, температура — параметр состояния.'],
['Работа расширения','При постоянном внешнем давлении w=−P_ext(V_final−V_initial). Расширение: ΔV>0 → w<0. Сжатие: ΔV<0 → w>0. 1 L·atm = 101.325 J. При переменном давлении нужна сумма по участкам или интеграл.'],
['Функции состояния','U,H,S,G зависят от состояния, их изменения — от начальной и конечной точки. q,w зависят от пути. Как высота горы: перепад высоты одинаков, а длина маршрута может отличаться.']
],['Газ поглотил 45 kJ теплоты и совершил 15 kJ работы.','q=+45 kJ, w=−15 kJ. ΔU=45−15=+30 kJ. Энергия газа выросла, хотя часть поступившей энергии ушла на работу.'],'Фраза work done by the gas иногда означает положительную величину отданной работы. В химическом соглашении w в ΔU=q+w для расширения отрицательна.'),
L('heat','thermo','Нагрев и смешивание','Heat capacity & thermal balance','Лекция 13, с. 27–31; Mid №3,15',
'Чтобы нагреть большую кастрюлю, нужно больше энергии, чем маленькую чашку. Ещё важен материал: разные вещества по-разному сопротивляются изменению температуры.',[
['Три теплоёмкости','Удельная c: J/(g·K), q=mcΔT. Молярная Cₘ: J/(mol·K), q=nCₘΔT. Полная C: J/K, q=CΔT. Всегда проверь, что именно дано.'],
['Нагрев и охлаждение','ΔT=T_final−T_initial. При нагревании q положительно. При охлаждении отрицательно. Если неизвестна температура, ΔT=q/(mc). Для 5 mol воды массу считаем как 5×18=90 g.'],
['Смешивание без потерь','q_hot+q_cold=0. Для одного вещества без фазового перехода T_final=(m₁T₁+m₂T₂)/(m₁+m₂). Для разных веществ вместо масс используй m₁c₁ и m₂c₂. Если ёмкость поглощает тепло, добавь C_cal(T_final−T_cal,initial).'],
['Проверка результата','Без реакции и фазового перехода конечная температура должна лежать между исходными. Если одна порция вдвое тяжелее, её температура сильнее влияет на результат.']
],['1050 J передали 5 mol воды, c=4.18 J/(g·K).','m=5×18=90 g. ΔT=1050/(90×4.18)=2.79 K. Делить на 5 вместо 90 нельзя: c дана на грамм, а не на моль.'],'K и °C одинаковы для ΔT, но это не разрешает использовать °C вместо T в PV=nRT.'),
L('phase','thermo','Лёд → вода → пар: собираем маршрут','Heating curves & phase transitions','Лекция 13, с. 37–42; лекция 14, с. 6–11; Quiz №4',
'При плавлении энергия тратится на перестройку взаимодействий между молекулами. Температура в идеализированном фазовом переходе при постоянном давлении остаётся постоянной.',[
['Раздели путь на кусочки','Нагрев льда до 0 °C: mc_iceΔT. Плавление: nΔH_fus. Нагрев воды до 100 °C: mc_waterΔT. Испарение: nΔH_vap. Если нужен горячий пар, добавь mc_steamΔT.'],
['Единицы решают','Если ΔH дана в kJ/mol — умножай на mol. Если в kJ/kg — на kg. Нельзя использовать 3600 g с константой в kJ/kg.'],
['Обратные процессы','Плавление, испарение, сублимация требуют тепла: положительный знак. Замерзание, конденсация, осаждение из газа отдают тепло: отрицательный знак. Для согласованных температур по закону Гесса ΔH_sub=ΔH_fus+ΔH_vap.'],
['График нагрева','Наклонные участки — меняется T, работаем с теплоёмкостью. Горизонтальные — меняется фаза, работаем с энтальпией перехода. Плато не означает, что теплота перестала поступать.']
],['1 kg льда при −10 °C превратить в пар при 100 °C. c_ice=2.11, c_water=4.18 kJ/(kg·K), L_fus=333.6, L_vap=2257 kJ/kg.','q₁=21.1; q₂=333.6; q₃=418; q₄=2257 kJ. Сумма 3029.7 kJ. Каждому этапу соответствует отдельное физическое изменение.'],'Нельзя считать всё как mcΔT от −10 до 100 °C: так пропадёт теплота плавления и испарения.'),
L('enthalpy','thermo','Энтальпия и калориметр','Enthalpy & calorimetry','Лекция 13, с. 32–45; лекция 14, с. 1–23; Quiz №17',
'Калориметр измеряет нагрев окружающей реакцию воды и прибора. Если вода нагрелась, реакция отдала ей энергию.',[
['Энтальпия','H=U+PV. При постоянном давлении и только PV-работе q_p=ΔH. При постоянном объёме без другой работы q_v=ΔU. Для реакции идеальных газов при одной T: ΔH=ΔU+Δn_gas RT, где Δn_gas — сумма коэффициентов газообразных продуктов минус реагентов на записанную реакцию.'],
['Coffee-cup calorimeter','q_solution=mcΔT. При пренебрежимой теплоёмкости стакана q_rxn=−q_solution. Если нужна энергия на mol, раздели q_rxn на количество прореагировавшего вещества, указанного в вопросе.'],
['Bomb calorimeter','Объём постоянный. q_rxn=−(mc_water+C_bomb)ΔT. Если дана полная теплоёмкость всей установки C_total, используй −C_totalΔT и не добавляй воду второй раз.'],
['Калибровка','Горячая вода отдаёт тепло холодной воде и прибору. C_cal=[m_hot c(T_hot−T_f)−m_cold c(T_f−T_cold)]/(T_f−T_cal,initial). В лекции прибор изначально имеет температуру холодной воды.'],
['Знак и масштаб','Exothermic: ΔH<0; endothermic: ΔH>0. ΔH для уравнения зависит от коэффициентов. Для 2 mol вещества выделится вдвое больше энергии, чем для 1 mol при той же реакции.']
],['Сгорело 0.200 g вещества, M=60.0 g/mol, C_total=3500 J/K, ΔT=1.60 K.','q_rxn=−3500×1.60=−5600 J. n=0.200/60=0.003333 mol. ΔU_m=−1680 kJ/mol. Если спрашивают energy released, величина выделенной энергии 1680 kJ/mol.'],'Не приравнивай q к ΔU просто потому, что давление не постоянно: нужна информация о работе и ограничениях процесса.'),
L('gas-thermo','thermo','Энергия идеального газа и разные пути','Heat capacities & PV paths','Лекция 14, с. 24–35; Quiz №3,16',
'У идеального газа внутренняя энергия зависит только от температуры. Путь влияет на теплоту и работу, но не на итоговое ΔU между одними и теми же состояниями.',[
['Одноатомный газ','C_v=3R/2 и C_p=5R/2 в расчёте на mol. ΔU=nC_vΔT, ΔH=nC_pΔT. Для любого идеального газа C_p−C_v=R; у многоатомного газа есть вращательные и колебательные вклады, поэтому 3R/2 обычно недостаточно.'],
['Изохора и изобара','При V=const: w=0, q=ΔU. При P=const: w=−nRΔT, q=ΔH. Для идеального газа с постоянными теплоёмкостями ΔU и ΔH по ΔT можно считать для любого пути.'],
['Маршрут на P–V графике','Горизонтальный участок: w=−PΔV. Вертикальный: ΔV=0, w=0. Сложи работы всех участков. Площадь под путём даёт величину работы расширения. Более высокое внешнее давление → больше отданной работы.'],
['Не перепутай C_p с C_v','Если дан C_p=20.8 J/(mol·K) для He, для ΔU используй C_v=20.8−8.314≈12.49. q при постоянном P и ΔU — разные величины.']
],['Из (2 atm,10 L) в (1 atm,30 L) двумя прямоугольными путями.','Сначала расширение при 2 atm: w=−2×20×101.325=−4053 J. Сначала снижение P при постоянном V, потом расширение при 1 atm: w=−2026.5 J. Начальная и конечная температуры одинаковы для обоих путей, поэтому ΔU совпадает.'],'Зависимость q,w от пути не нарушает сохранение энергии: их сумма остаётся одинаковой.'),
L('hess','thermo','Закон Гесса: химические уравнения как пазл','Hess law & formation enthalpy','Лекция 14, с. 36–48; Mid №13; Quiz №9',
'Если две дороги приводят в одно конечное состояние, изменение энтальпии одинаково. Поэтому сложную реакцию можно собрать из известных.',[
['Три действия','Перевернул реакцию → поменял знак ΔH. Умножил все коэффициенты на число → умножил ΔH на то же число. Сложил реакции → сложил ΔH. Промежуточные вещества сокращаются только с противоположных сторон.'],
['Через энтальпии образования','ΔH°_rxn=ΣνΔH°_f(products)−ΣνΔH°_f(reactants). ΔH°_f — образование 1 mol вещества из элементов в стандартных состояниях. Для элемента в стандартной устойчивой форме ΔH°_f=0. Для O₂(g) — ноль; для O(g) и O₃ — нет.'],
['Фаза имеет значение','H₂O(l) и H₂O(g) имеют разные ΔH°_f. Нельзя брать строку газа, если в уравнении жидкость. В современной конвенции стандартное давление 1 bar; в старых слайдах 1 atm. Для расчёта используй одну согласованную таблицу.'],
['Масса топлива и КПД','Нужная энергия топлива = полезная энергия/η. Затем n=|q_fuel|/|ΔH_combustion|, m=nM. Для КПД 80% η=0.80. Деление на 0.8 даёт больше топлива, что физически разумно.']
],['CH₄ + NH₃ → HCN + 3H₂. ΔH_f(CH₄)=−74.9, ΔH_f(NH₃)=−45.9, ΔH_f(HCN)=135.15 kJ/mol.','Продукты:135.15+3×0. Реагенты:−74.9−45.9=−120.8. ΔH=135.15−(−120.8)=255.95 kJ. Реакция требует тепло.'],'Products minus reactants. Отрицательные числа в сумме реагентов нужно вычитать со скобками.'),
L('cycles','thermo','Энергии связей и цикл Борна — Габера','Bond enthalpy & Born–Haber cycle','Лекция 14, с. 49–52; лекция 15, с. 1–10',
'Можно мысленно разобрать вещества на части и собрать заново. Энергия разборки стоит со знаком плюс, сборки — обычно со знаком минус.',[
['Средние энергии связей','ΔH≈ΣD(bonds broken)−ΣD(bonds formed). Разрыв связи требует энергию. Образование связи выделяет энергию. Средние D дают приближение, особенно для газовой фазы; табличные ΔH_f обычно точнее.'],
['Не считай неизменившиеся связи','В CH₄+Cl₂→CH₃Cl+HCl реально меняются одна C–H и одна Cl–Cl на одну C–Cl и одну H–Cl. Остальные C–H сокращаются.'],
['Цикл NaCl','Na(s)→Na(g): атомизация +108. Na(g)→Na⁺+e⁻: ионизация +496. ½Cl₂→Cl: +121. Cl+e⁻→Cl⁻: присоединение электрона −349. Ионы→NaCl(s): неизвестная энтальпия образования решётки. Всё в kJ/mol.'],
['Два знака решёточной энтальпии','Formation: газовые ионы → кристалл, отрицательная. Dissociation: кристалл → газовые ионы, положительная. В данном курсе обычно требуется dissociation. Направление процесса важнее слова lattice energy.'],
['Изменение температуры перехода','По циклу или закону Кирхгофа при постоянных теплоёмкостях ΔH(T₂)=ΔH(T₁)+ΔC_p(T₂−T₁). Для испарения ΔC_p=C_p(g)−C_p(l). Это позволяет перенести ΔH_vap с 373 K на 298 K.']
],['Найди lattice dissociation для NaCl, ΔH_f=−411 kJ/mol.','−411=108+496+121−349+ΔH_latt,form. Сумма первых четырёх =376. ΔH_form=−787. Обратный процесс dissociation: +787 kJ/mol.'],'Присоединение электрона к Cl — electron affinity, не энергия отрыва электрона.'),
L('equilibrium','eq','Равновесие, K и Q','Dynamic equilibrium & reaction quotient','Лекция 15, с. 11–30; Mid №19',
'Представь две двери между комнатами: за минуту в каждую сторону проходит одинаковое число людей. Количество людей в комнатах постоянно, хотя движение продолжается.',[
['Динамическое равновесие','Прямая и обратная реакции идут с одинаковой скоростью. Концентрации постоянны, но не обязаны быть равными. Просто неизменные концентрации ещё не доказывают равновесие: реакция может быть очень медленной.'],
['Записываем K','Для aA+bB⇌cC+dD: K_c=[C]^c[D]^d/([A]^a[B]^b). Коэффициенты становятся степенями. Чистые твёрдые и чистые жидкости не включаем. Большое K означает преимущество продуктов при равновесии, а не высокую скорость реакции.'],
['Q показывает, куда идти','Q считается по той же формуле из текущих значений. Q<K → вправо; Q>K → влево; Q=K → равновесие. Если продуктов нет, а реагенты есть, Q=0 и обычно система движется к продуктам.'],
['Активность','Строгая константа равновесия безразмерна и выражается через активности. Для разбавленного раствора a≈c/c°, более точно a=γc/c°. Для идеального газа a=P/P°. Чистому конденсированному веществу соответствует a≈1, пока эта фаза присутствует.'],
['Меняем уравнение','Перевернуть реакцию: K_new=1/K. Умножить коэффициенты на r: K_new=K^r. Сложить реакции: перемножить K. Не переносить правила сложения ΔH на K.']
],['Для N₂+3H₂⇌2NH₃: [N₂]=1, [H₂]=2, [NH₃]=2 M. K_c=1. Куда пойдёт реакция?','Q=2²/(1×2³)=0.5. Q<K, продуктов недостаточно по сравнению с равновесием. Сдвиг вправо.'],'Константа K при фиксированной температуре не меняется от добавления реагента; меняется состав.'),
L('ice','eq','ICE-таблица шаг за шагом','Initial–Change–Equilibrium','Лекция 15, с. 31–35; Quiz №8',
'ICE — способ не держать всё в голове. В каждой строке пишем: сколько было, что изменилось, сколько стало.',[
['Один неизвестный x','Для A+B⇌2C при исходных a,b,c: I: a,b,c. C: −x,−x,+2x. E: a−x,b−x,c+2x. x — не обязательно концентрация продукта: коэффициент 2 даёт 2x.'],
['Как решить','1. Переведи моли в концентрации. 2. Проверь Q и направление. 3. Запиши ICE с коэффициентами. 4. Подставь E-строку в K. 5. Реши уравнение. 6. Отбрось корни с отрицательными концентрациями. 7. Подставь ответ обратно в K.'],
['Когда можно приближать','Для маленького K иногда x мало относительно исходной концентрации. После расчёта проверь фактическое изменение, включая коэффициент: например 2x/c₀≤5%. Малое K само по себе не является доказательством допустимости приближения.'],
['Удобный симметричный случай','A+B⇌C+D, все исходно c₀. K=((c₀+x)/(c₀−x))². r=√K; x=c₀(r−1)/(r+1). Если K<1, x отрицателен: это нормально, реакция идёт в обратную сторону.']
],['SO₂+NO₂⇌SO₃+NO, все исходно 0.8 M, K=3.75. Найди [SO₃].','r=√3.75=1.9365. x=0.8×(1.9365−1)/(1.9365+1)=0.2551 M. [SO₃]=0.8+x=1.0551≈1.1 M. Проверка: (1.0551/0.5449)²=3.75.'],'Если x выходит больше, чем есть реагента с учётом коэффициента, корень физически невозможен.'),
L('shifts','eq','Kp и принцип Ле Шателье','Kp & Le Chatelier principle','Лекция 15, с. 20–28, 36–40; Mid №7; Quiz №12',
'Система после изменения условий стремится к новому равновесию. Удобно думать: какое направление уменьшит внесённое изменение?',[
['Kp и Kc','В учебной форме K_p=K_c(RT)^Δn_gas. Для N₂+3H₂⇌2NH₃ Δn=2−4=−2. Если используешь давления в atm и концентрации в mol/L, R=0.082057. В строгой записи через активности учитываются стандартные состояния.'],
['Концентрация','Добавил реагент → обычно вправо. Добавил продукт → влево. Удалил продукт → вправо. Добавление чистого твёрдого вещества не меняет равновесные концентрации, пока эта фаза уже присутствует.'],
['Сжатие','Уменьшение V при постоянной T смещает газовое равновесие к меньшему числу молей газа. Если количества газовых коэффициентов равны — сдвига нет. Не считай твёрдые и жидкости. K при этом не меняется.'],
['Инертный газ и катализатор','Инертный газ при постоянном V не меняет парциальные давления реагирующих газов: сдвига нет. При постоянном общем P он увеличивает V, что может сдвинуть к большему числу молей газа. Катализатор ускоряет достижение равновесия в обе стороны, но не меняет K или равновесный состав.'],
['Температура','У экзотермической реакции «тепло справа»: нагрев сдвигает влево и уменьшает K. У эндотермической нагрев сдвигает вправо и увеличивает K. Только температура из перечисленных воздействий меняет K для заданной реакции.']
],['Как увеличить равновесный выход NH₃ в экзотермическом Haber process?','N₂+3H₂⇌2NH₃. Справа 2 mol газа, слева 4. Повышение давления сжатием и снижение T увеличивают равновесный выход. На производстве слишком низкая T неудобна из-за медленной реакции.'],'Большой выход по термодинамике не означает быструю реакцию.'),
L('acid-basics','acid','Кто отдаёт протон, а кто принимает','Acids, bases & conjugate pairs','Лекция 16, с. 1–10, 23–29, 32; Quiz №2',
'В определении Бренстеда кислота отдаёт H⁺, основание принимает. После передачи они превращаются в сопряжённую пару.',[
['Три определения','Arrhenius: кислота увеличивает H₃O⁺ в воде, основание — OH⁻. Brønsted–Lowry: донор и акцептор протона. Lewis: кислота принимает электронную пару, основание отдаёт. BF₃ — Lewis acid, хотя в нём нет H.'],
['Сопряжённая пара','HA → H⁺+A⁻: A⁻ — conjugate base. B+H⁺→BH⁺: BH⁺ — conjugate acid. Пара отличается ровно одним H⁺; при потере H⁺ заряд уменьшается на 1. H₂CO₃/HCO₃⁻ — пара, H₂CO₃/CO₃²⁻ — не соседняя сопряжённая пара.'],
['Сила и концентрация','Сильная кислота почти полностью ионизована в разбавленном водном растворе. Слабая — частично. Разбавленная сильная и концентрированная слабая — возможные сочетания: сила не равна концентрации. HCl,HBr,HI,HNO₃,HClO₄ обычно считают сильными; HF и CH₃COOH — слабыми.'],
['Ka и Kb','K_a=[H⁺][A⁻]/[HA]; K_b=[BH⁺][OH⁻]/[B]. Чем больше K_a, тем сильнее кислота; pK_a=−log K_a, поэтому меньший pK_a означает сильнее. Для сопряжённой пары K_aK_b=K_w. При 25 °C pK_a+pK_b=14.']
],['Сопряжённое основание NH₄⁺?','Убери один H⁺: NH₄⁺→NH₃+H⁺. Ответ NH₃. Заряд +1 стал 0. Электроны связи остаются у N, образуя lone pair.'],'H⁺ в воде — удобное сокращение для гидратированного протона, часто записываемого как H₃O⁺.'),
L('ph','acid','pH и сильные кислоты и основания','pH, pOH & water autoionization','Лекция 16, с. 4, 11, 14–17, 24',
'pH — компактная запись очень маленькой концентрации H⁺. Уменьшение pH на единицу означает примерно десятикратное увеличение H⁺ в идеальном разбавленном растворе.',[
['Базовые связи','pH=−log[H⁺]; [H⁺]=10^(−pH). pOH=−log[OH⁻]. K_w=[H⁺][OH⁻]=10⁻¹⁴ при 25 °C. Поэтому pH+pOH=14 при 25 °C. В другой температуре вместо 14 используют pK_w.'],
['Сильная одноосновная кислота','Для достаточно концентрированного относительно 10⁻⁷ M раствора HCl: [H⁺]≈c. Например c=0.010 M даёт pH=2. Это приближение не подходит для сверхразбавленных растворов.'],
['Сильное основание','NaOH даёт один OH⁻ на формульную единицу, Ca(OH)₂ — два, если полностью растворено. Сначала найди [OH⁻], затем pOH, потом pH=14−pOH.'],
['Очень разбавленная сильная кислота','Нужно учитывать воду. Для одноосновной кислоты концентрации c: h=[H⁺]=(c+√(c²+4K_w))/2. Это следует из h=c+[OH⁻] и [OH⁻]=K_w/h. Нельзя просто прибавить 10⁻⁷ к c: кислота подавляет автоионизацию воды.'],
['Нейтральность','Нейтральный раствор имеет [H⁺]=[OH⁻]. pH=7 нейтрален именно при 25 °C. Шкала 0–14 не является строгим универсальным пределом, особенно для концентрированных растворов.']
],['pH раствора HNO₃ 1.0×10⁻⁷ M при 25 °C?','h=(10⁻⁷+√(10⁻¹⁴+4×10⁻¹⁴))/2=1.618×10⁻⁷ M. pH≈6.79. Раствор слегка кислый, не нейтральный и не щелочной.'],'После расчёта слабого основания ты получаешь OH⁻, а не H⁺. Не называй pOH ответом на вопрос о pH.'),
L('weak','acid','Слабая кислота и правило 5%','Weak acid/base calculations','Лекция 16, с. 12–13, 30–31',
'Слабая кислота отдаёт протоны только частично. Поэтому её исходная концентрация больше, чем равновесная концентрация H⁺.',[
['ICE для HA','HA⇌H⁺+A⁻. Исходно c,0,0. Изменения −x,+x,+x. Равновесие c−x,x,x. K_a=x²/(c−x). Вклад воды здесь пренебрежим, если x значительно больше 10⁻⁷ M.'],
['Быстрое приближение','Если x≪c, то c−x≈c и x≈√(K_ac). Проверь 100x/c≤5%. Потом pH=−log x. Проверка приближения — часть решения, не необязательное украшение.'],
['Точный квадратный корень','Если приближение не прошло: x=(−K_a+√(K_a²+4K_ac))/2. Эквивалентная устойчивая форма: x=2K_ac/(K_a+√(K_a²+4K_ac)). Точность этой модели всё ещё предполагает идеальный раствор и пренебрежимый вклад воды.'],
['Слабое основание','B+H₂O⇌BH⁺+OH⁻. Теперь x=[OH⁻], K_b=x²/(c−x). Алгоритм тот же; в конце pOH=−log x и pH=14−pOH при 25 °C.'],
['Процент ионизации','% ionization=100x/c. При разбавлении слабой кислоты процент ионизации обычно растёт, хотя абсолютная [H⁺] падает.']
],['HF: c=1.00 M, K_a=7.2×10⁻⁴.','x≈√0.00072=0.02683 M; 2.68%<5%. pH≈1.57. Квадратное решение x≈0.02648 даёт pH≈1.58. Различие — допустимое приближение, а не разные вещества.'],'Вычитание x из c нельзя отбросить без последующей проверки.'),
L('poly','acid','Многоосновные кислоты и соли','Polyprotic acids & salt hydrolysis','Лекция 16, с. 18–22, 37–38; Mid №5',
'Многоосновная кислота отдаёт протоны по ступенькам. Обычно каждый следующий протон отнять труднее: частица уже стала отрицательной.',[
['Три ступени','H₃A⇌H⁺+H₂A⁻ (K₁); H₂A⁻⇌H⁺+HA²⁻ (K₂); HA²⁻⇌H⁺+A³⁻ (K₃). Для многих кислот K₁≫K₂≫K₃. Тогда первую ступень используют для оценки pH; для других случаев нужна совместная система равновесий.'],
['Малые последующие формы','Если первая ступень доминирует: h≈[H₂A⁻]. Затем [HA²⁻]=K₂[H₂A⁻]/h≈K₂. [A³⁻]=K₃[HA²⁻]/h. Не путай большую оставшуюся [H₃A] с образовавшейся [H₂A⁻].'],
['Соли тоже влияют на pH','NaCl обычно нейтрален. F⁻ из NaF принимает H⁺ у воды и образует OH⁻: раствор основной. Для F⁻ K_b=K_w/K_a(HF). NH₄⁺ из NH₄Cl отдаёт H⁺: раствор кислый, K_a=K_w/K_b(NH₃).'],
['Соль слабой кислоты','Найди K_b аниона. Затем x≈√(K_bc_salt) — концентрация OH⁻, проверь приближение и переведи pOH в pH. Для амфипротных частиц, например HCO₃⁻, учитывается способность и принимать, и отдавать протон.']
],['H₃Cit: c=0.50 M, K₁=7.5×10⁻⁴, K₂=1.7×10⁻⁵, K₃=4.0×10⁻⁷.','h≈√(K₁c)=0.01936 M, pH≈1.71; [H₂Cit⁻]≈0.019 M. [HCit²⁻]≈1.7×10⁻⁵ M; [Cit³⁻]≈4.0×10⁻⁷×1.7×10⁻⁵/0.01936≈3.5×10⁻¹⁰ M. В примере мидки вариант с 0.48 M для H₂Cit⁻ ошибочен: это близко к оставшейся исходной кислоте.'],'Число протонов в формуле слабой кислоты не означает [H⁺]=3c.'),
L('buffer','acid','Буфер: сначала моли, потом логарифм','Buffers & Henderson–Hasselbalch','Лекция 16, с. 33–36; Mid №1; Quiz №7',
'Буфер содержит две «команды»: слабую кислоту HA, которая убирает добавленный OH⁻, и её основание A⁻, которое убирает добавленный H⁺.',[
['Состав и работа','Нужны заметные количества слабой кислоты и её сопряжённого основания или слабого основания и сопряжённой кислоты. Буфер смягчает небольшие добавки, но не способен поглотить неограниченное количество кислоты или щёлочи. Его pH не обязательно 7.'],
['Главная формула','pH=pK_a+log([A⁻]/[HA]). После смешивания в одном объёме отношение концентраций равно отношению молей. Если объёмы исходных растворов разные, сначала n=cV.'],
['Добавили сильную кислоту','H⁺+A⁻→HA: n_A уменьшается на добавленные mol H⁺, n_HA увеличивается на столько же. После стехиометрии подставляй новые количества.'],
['Добавили сильное основание','OH⁻+HA→A⁻+H₂O: n_HA уменьшается, n_A растёт. Если одна компонента исчерпана, нельзя использовать Henderson–Hasselbalch как будто буфер сохранился. Нужно считать избыток сильного реагента и/или новое слабое равновесие.'],
['Диапазон и ёмкость','При равных количествах pH=pK_a. Практический рабочий диапазон примерно pK_a±1, когда отношение A⁻/HA между 0.1 и 10. При том же отношении более концентрированный буфер обычно имеет большую ёмкость.']
],['250 mL 0.250 M HCOOH + 500 mL 0.500 M HCOONa, pK_a=3.75.','n_HA=0.250×0.250=0.0625 mol. n_A=0.500×0.500=0.250 mol. Отношение=4. pH=3.75+log4=4.352≈4.35.'],'Не используй отношение исходных концентраций 0.500/0.250: объёмы различаются.'),
L('entropy','entropy','Энтропия: сколько способов устроить систему','Entropy & microstates','Дополнение по Mid №11,17,20; в PDF 9–16 тема только анонсирована',
'Один и тот же видимый результат можно получить множеством расположений частиц. Чем больше доступных микросостояний, тем выше энтропия.',[
['Микро и макро','Macrostate задаётся макроскопическими параметрами: T,V,P,n. Microstate — конкретное микроскопическое распределение энергии и частиц, совместимое с макросостоянием. S=k_B ln W, где W — число доступных микросостояний. «Беспорядок» — лишь грубая аналогия.'],
['Когда S обычно растёт','Расширение газа, нагрев, переход твёрдое→жидкое→газ обычно увеличивают S. Для реакции ΔS°=ΣνS°_products−ΣνS°_reactants. Стандартная энтропия элемента при 298 K обычно не нулевая: не путай её с ΔH°_f.'],
['Второй закон','Для самопроизвольного процесса ΔS_universe=ΔS_system+ΔS_surroundings>0. В обратимом пределе равно 0. Энтропия самой системы может уменьшаться, если окружение увеличивает свою сильнее.'],
['Энтропия и теплота','Для обратимой передачи при постоянной T: ΔS=q_rev/T. Для фазового перехода при равновесной T: ΔS_transition=ΔH_transition/T. Для большого теплового резервуара ΔS_surroundings=−q_system/T; при постоянном P и только PV-работе =−ΔH_system/T.'],
['Изотермическое расширение','Идеальный газ при постоянной T: ΔU=0. Для обратимого расширения w=−nRT ln(V₂/V₁), q=−w, ΔS=nR ln(V₂/V₁). При расширении ΔS>0. Формулу обратимой работы нельзя применять к любому необратимому пути.']
],['1 mol идеального газа обратимо расширяется вдвое при 300 K.','w=−1×8.314×300×ln2=−1729 J; q=+1729 J; ΔU=0. ΔS=8.314×ln2=5.76 J/K.'],'Самопроизвольность — не скорость. Процесс может быть термодинамически выгоден, но почти не идти из-за кинетического барьера.'),
L('gibbs','entropy','Энергия Гиббса и температура процесса','Gibbs energy & spontaneity','Дополнение по Mid №4,8,14,20,25',
'При постоянных температуре и давлении энергия Гиббса помогает предсказать направление самопроизвольного изменения. Она объединяет энергетическую выгоду и энтропию.',[
['Знак ΔG','ΔG=ΔH−TΔS. При постоянных T,P и обычных условиях химической задачи: ΔG<0 — прямое направление самопроизвольно; >0 — обратное; =0 — равновесие. ΔG не даёт скорость реакции.'],
['Четыре комбинации','ΔH<0, ΔS>0: выгодно при всех T>0 в области применимости данных. ΔH>0, ΔS<0: невыгодно при всех T>0. ΔH<0, ΔS<0: выгодно при низкой T. ΔH>0, ΔS>0: выгодно при высокой T.'],
['Граничная температура','При ΔG=0: T*=ΔH/ΔS. Приведи ΔH и ΔS к одним единицам. Деление даёт Kelvin. Направление неравенства определяй по знакам, а не запоминай «T всегда больше». Обычно предполагают постоянные ΔH,ΔS в данном диапазоне.'],
['Кипение','При равновесии жидкости и пара ΔG_vap=0, поэтому T_b≈ΔH_vap/ΔS_vap. Если ΔH_vap=35.3 kJ/mol, ΔS_vap=105 J/(mol·K), получим 336.2 K, около 63 °C. Эти числа должны быть заданы: отсутствующую таблицу экзамена нельзя угадывать.'],
['Не стандартные условия','ΔG=ΔG°+RT ln Q. ΔG°=−RT ln K. В Q чистые твёрдые и жидкости не входят. При равновесии Q=K и ΔG=0, но ΔG° не обязана равняться нулю. Для Pb(s)+O₂(g)→PbO₂(s): Q=1/(P_O₂/P°).']
],['ΔH=−92.4 kJ, ΔS=−198 J/K. Когда прямая реакция выгодна?','ΔG=−92.4+0.198T kJ. Условие ΔG<0: T<92.4/0.198=466.7 K. Именно ниже границы, а не выше.'],'В уравнении синтеза аммиака сначала исправь баланс: N₂+3H₂→2NH₃. Не используй неуравненную запись из копии примера.')
];

export const glossary=[['amount of substance','количество вещества, n (mol)'],['molar mass','молярная масса, M (g/mol)'],['mole fraction','мольная доля, χ'],['lone pair','неподелённая электронная пара'],['bonding / antibonding','связывающая / разрыхляющая орбиталь'],['bond order','порядок связи'],['bond length','длина связи'],['paramagnetic','есть неспаренные электроны'],['effusion','выход газа через малое отверстие'],['mean free path','средний свободный пробег'],['surroundings','окружающая среда'],['heat released','выделенная теплота (величина)'],['heat absorbed','поглощённая теплота'],['constant volume','постоянный объём'],['constant pressure','постоянное давление'],['reversible','обратимый'],['isothermal','при постоянной температуре'],['enthalpy of formation','энтальпия образования'],['lattice dissociation','разрушение решётки на газовые ионы'],['reaction quotient','реакционное отношение Q'],['equilibrium yield','равновесный выход'],['conjugate base','сопряжённое основание'],['negligible','пренебрежимо малый'],['spontaneous','самопроизвольный, не обязательно быстрый'],['estimate / calculate','оцените приближённо / вычислите'],['FALSE / NOT correct','выберите неверное утверждение']];

